    use crate::Checker;

    fn with_checker<R>(source: &str, test: impl FnOnce(&mut Checker<'_, '_>, NodeId) -> R) -> R {
        let arena = Arena::new();
        let parsed = tsr_parser::parse(&arena, source);
        assert!(parsed.diagnostics.is_empty());
        let bound = tsr_binder::bind(
            &arena,
            parsed.source_file,
            &parsed.nodes,
            tsr_binder::FileInfo { name: "test.ts", text: source },
        );
        let root = parsed.source_file.node_id().unwrap();
        let mut checker = Checker::new(&bound, &parsed.nodes, &parsed.node_map);
        test(&mut checker, root)
    }


    #[test]
    fn member_consumer_common_self_keeps_alias_after_inheritance() {
        let source = "interface Base { self: this } interface Left extends Base { l: number } interface Right extends Base { r: string } type Both = Left & Right; declare const value: Both; const probe = value.self;";
        for expression_first in [false, true] {
            with_checker(source, |checker, root| {
                if expression_first {
                    let probe = checker.binder.lookup_local(root, "probe").unwrap();
                    checker.get_type_of_symbol(probe);
                }
                let both = checker.binder.lookup_local(root, "Both").unwrap();
                let receiver = checker.get_declared_type_of_symbol(both);
                for _ in 0..3 {
                    let read = checker.get_type_of_property_of_type(receiver, "self").unwrap();
                    assert_eq!(checker.type_to_string(read), "Both");
                }
            });
        }
    }

