#[test]
fn member_consumer_generic_reads_do_not_merge_on_bare_symbol() {
    use crate::member_completeness::{MemberConsumerResult as Result, MemberConsumerIdentity as Identity};
    let prefix = "interface Base<T> { value:T } interface Left<U> extends Base<U> { left:U } interface Right<V> extends Base<V> { right:V }";
    for (body, expected_read, expected_identity) in [
        ("type Both = Left<string> & Right<string>;", "string", Identity::Single),
        ("type Both = Left<string> & Right<number>;", "never", Identity::Synthesized),
    ] {
        let source = format!("{prefix} {body} declare const receiver:Both; const probe=receiver.value;");
        for order in 0..3 {
            with_checker(&source, |checker, root| {
                if order == 1 {
                    let probe = checker.binder.lookup_local(root, "probe").unwrap();
                    checker.get_type_of_symbol(probe);
                } else if order == 2 {
                    checker.check_source_file(root, crate::check::FileContext {ambient:false, has_parse_errors:false});
                }
                let both = checker.binder.lookup_local(root, "Both").unwrap();
                let receiver = checker.get_declared_type_of_symbol(both);
                let Result::Complete(first) = checker.member_consumer_view(receiver, "value") else { panic!("no completed generic view"); };
                assert_eq!(checker.type_to_string(first.read), expected_read);
                assert_eq!(first.identity, expected_identity);
                assert_eq!(first.receiver, receiver);
                for _ in 0..3 {
                    assert_eq!(checker.member_consumer_view(receiver, "value"), Result::Complete(first.clone()));
                }
            });
        }
    }
}

#[test]
fn member_consumer_equal_reads_keep_distinct_declaration_origins() {
    use crate::member_completeness::{MemberConsumerResult as Result, MemberConsumerIdentity as Identity};
    with_checker("interface Left {value:string; left:number} interface Right {value:string; right:number} type Both = Left & Right;", |checker, root| {
        let both = checker.binder.lookup_local(root, "Both").unwrap();
        let receiver = checker.get_declared_type_of_symbol(both);
        let Result::Complete(view) = checker.member_consumer_view(receiver, "value") else { panic!("view"); };
        assert_eq!(checker.type_to_string(view.read), "string");
        assert_eq!(view.identity, Identity::Synthesized);
    });
}

#[test]
fn member_consumer_generic_accessor_preserves_first_write_context() {
    use crate::member_completeness::{MemberConsumerResult as Result, MemberConsumerIdentity as Identity};
    let prefix = "class Base<T> { get value():number {return 0;} set value(v:T) {} } class Left<U> extends Base<U> {declare left:U} class Right<V> extends Base<V> {declare right:V}";
    for (body, expected_write) in [
        ("type Both=Left<string>&Right<number>;", "string"),
        ("type Both=Right<number>&Left<string>;", "number"),
    ] {
        let source = format!("{prefix} {body} declare const receiver:Both; const probe=receiver.value;");
        for order in 0..3 {
            with_checker(&source, |checker, root| {
                if order == 1 {
                    let probe = checker.binder.lookup_local(root, "probe").unwrap();
                    checker.get_type_of_symbol(probe);
                } else if order == 2 {
                    checker.check_source_file(root, crate::check::FileContext {ambient:false, has_parse_errors:false});
                }
                let both = checker.binder.lookup_local(root, "Both").unwrap();
                let receiver = checker.get_declared_type_of_symbol(both);
                let Result::Complete(view) = checker.member_consumer_view(receiver, "value") else { panic!("accessor view"); };
                assert_eq!(checker.type_to_string(view.read), "number");
                assert_eq!(view.identity, Identity::Merged);
                assert_eq!(checker.type_to_string(view.write.expect("setter write")), expected_write);
                assert_eq!(checker.member_consumer_view(receiver, "value"), Result::Complete(view));
            });
        }
    }
}

#[test]
fn member_consumer_active_bases_are_not_completed_empty_members() {
    use crate::member_completeness::MemberConsumerResult as Result;
    use crate::resolution::PropertyName;
    with_checker("interface Root {root:number} interface A extends Root {own:string}", |checker, root| {
        let symbol = checker.binder.lookup_local(root, "A").unwrap();
        let receiver = checker.get_declared_type_of_symbol(symbol);
        // Explicit frame countercontrol, not a claimed natural nested
        // callback. The native producer separately qualifies natural reentry.
        assert!(checker.resolutions.push(symbol, PropertyName::ResolvedBaseTypes));
        assert_eq!(checker.member_consumer_view(receiver, "own"), Result::Active {prefix:vec![]});
        assert!(!checker.resolutions.pop(), "base reentry marked the cycle frame");
        let Result::Complete(view) = checker.member_consumer_view(receiver, "own") else {panic!("own completion");};
        assert_eq!(checker.type_to_string(view.read), "string");
        let Result::Complete(view) = checker.member_consumer_view(receiver, "root") else {panic!("base completion");};
        assert_eq!(checker.type_to_string(view.read), "number");
        assert_eq!(checker.resolutions.depth(), 0);
        assert_eq!(checker.member_consumer_view(receiver, "missing"), Result::Unsupported);
    });
}

#[test]
fn member_consumer_uses_filtered_cycle_bases_and_keeps_valid_prefixes() {
    use crate::member_completeness::MemberConsumerResult as Result;
    let source = "interface Root {root:number} interface Later {later:number} interface A<T> extends Root,B<T>,Later {a:T} interface B<T> extends A<T> {b:T} type Seen=A<string>;";
    with_checker(source, |checker, root| {
        let symbol = checker.binder.lookup_local(root, "A").unwrap();
        let bases = checker.get_base_types(symbol);
        assert_eq!(bases.iter().map(|&base| checker.type_to_string(base)).collect::<Vec<_>>(), ["Root", "Later"]);
        let seen = checker.binder.lookup_local(root, "Seen").unwrap();
        let receiver = checker.get_declared_type_of_symbol(seen);
        for name in ["root", "later"] {
            let Result::Complete(view) = checker.member_consumer_view(receiver, name) else {panic!("valid base view");};
            assert_eq!(checker.type_to_string(view.read), "number");
        }
        assert_eq!(checker.member_consumer_view(receiver, "b"), Result::Unsupported);
    });
}

