#[test]
fn member_consumer_scalar_completion_matches_native_query_history() {
    use crate::member_completeness::{MemberConsumerResult as Result, MemberConsumerIdentity as Identity};
    let source = "interface Base<T> {value:number} interface Left<U> extends Base<U> {left:U} interface Right<V> extends Base<V> {right:V} type Both=Left<string>&Right<number>; declare const receiver:Both; const probe=receiver.value;";
    let mut observed = Vec::new();
    for order in 0..3 {
        with_checker(source, |checker, root| {
            if order == 1 {
                let probe = checker.binder.lookup_local(root, "probe").unwrap();
                checker.get_type_of_symbol(probe);
            } else if order == 2 {
                checker.check_source_file(root, crate::check::FileContext {ambient:false, has_parse_errors:false});
            }
            let both = checker.binder.lookup_local(root, "Both").unwrap();
            let receiver = checker.get_declared_type_of_symbol(both);
            let Result::Complete(view) = checker.member_consumer_view(receiver, "value") else {panic!("scalar view");};
            // Exact qualified native .29 table: receiver-first and checked-
            // first reuse the resolved invariant original symbol; expression-
            // first retains its earlier merged-instantiation clone.
            observed.push(view.identity.clone());
            assert_eq!(checker.type_to_string(view.read), "number");
        });
    }
    assert_eq!(observed, [Identity::Single, Identity::Merged, Identity::Single]);
}

