/// Query-local prototype, never a general member-completion or absence cache.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum MemberConsumerResult {
    Complete(MemberConsumerView),
    Active { prefix: Vec<crate::types::TypeId> },
    Failed,
    Unsupported,
}

/// IDs are valid only in the private checker executing this request.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct MemberConsumerView {
    pub root: tsr_binder::SymbolId,
    pub supplier: crate::types::TypeId,
    pub receiver: crate::types::TypeId,
    pub read: crate::types::TypeId,
    pub write: Option<crate::types::TypeId>,
    pub optional: bool,
    pub readonly: bool,
    pub accessibility: u8,
    pub identity: MemberConsumerIdentity,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum MemberConsumerIdentity {
    Single,
    Merged,
    Synthesized,
}

